D={
83001:("Past perfect continuous","**Had been + -ing**: ação que durava até um momento passado e explica um estado.",[("She {{had been planning}} the trip for months.","Ela vinha planejando a viagem havia meses."),("He was soaked because he {{had been walking}} in the rain.","Ele estava encharcado porque vinha caminhando na chuva."),("We {{had been waiting}} for an hour when the bus came.","Esperávamos havia uma hora quando o ônibus chegou."),("Her eyes were red; she {{had been crying}}.","Os olhos dela estavam vermelhos; ela estivera chorando.")],"Qual explica a causa de um estado?",["He had been running, so he was tired.","He ran, so he is tired.","He runs, so he was tired."],0,"Had been running → causa do cansaço."),
83002:("Future perfect continuous","**Will have been + -ing**: quanto tempo algo terá durado num ponto do futuro.",[("By June, I {{will have been working}} here for ten years.","Em junho, estarei trabalhando aqui há dez anos."),("By then, they {{will have been living}} abroad for a decade.","Até lá, estarão morando fora há uma década."),("She {{will have been studying}} for six hours by midnight.","Ela terá estudado por seis horas até a meia-noite."),("{{How long will you have been}} waiting?","Há quanto tempo você estará esperando?")],"Qual usa o tempo certo?",["By May I will have been teaching for five years.","By May I am teaching five years.","By May I had been teaching."],0,"By + tempo → will have been + -ing."),
83003:("Tempos narrativos","**Past simple** (fatos), **past continuous** (cenário), **past perfect** (antes).",[("While she {{was cleaning}}, she {{discovered}} a letter.","Enquanto limpava, ela descobriu uma carta."),("Her mother {{had hidden}} it years before.","A mãe dela a tinha escondido anos antes."),("It {{was getting}} dark when we {{reached}} the cabin.","Escurecia quando chegamos à cabana."),("By then, the others {{had gone}} home.","Até então, os outros tinham ido para casa.")],"Qual verbo mostra o que veio antes?",["discovered","was cleaning","had hidden"],2,"Past perfect."),
83004:("used to / would / be used to","**Used to** = hábito ou estado que acabou; **would** só para ações repetidas; **be used to + -ing** = estar acostumado.",[("We {{used to play}} outside until dark.","Costumávamos brincar fora até escurecer."),("I {{used to be}} shy, but now I'm confident.","Eu era tímido, mas agora tenho confiança."),("I'm {{used to waking}} up early.","Estou acostumado a acordar cedo."),("It took months to {{get used to}} the noise.","Levou meses para me acostumar ao barulho.")],"Qual frase NÃO aceita would?",["We would visit her every Sunday.","I would have a red bicycle.","She would bake bread at dawn."],1,"Estado (ter): só used to."),
83005:("Presente histórico","Contar no **presente** deixa a cena viva (piadas, resumos, relatos).",[("So I {{grab}} my coat and {{run}} outside.","Então pego o casaco e saio correndo."),("It {{turns out}} the shop is closed.","Acontece que a loja está fechada."),("And guess what I {{see}}?","E adivinha o que eu vejo?"),("In the film, the hero {{finds}} a map.","No filme, o herói encontra um mapa.")],"O presente histórico serve para…",["dar vivacidade a um relato","falar do futuro","dar ordens"],0,"Vivacidade."),
940001:("bank on / rope in","**Bank on** = contar com; **tide over** = socorrer por um tempo; **rope in** = chamar para ajudar; **fob off** = enrolar.",[("You can {{bank on}} good news.","Pode contar com boas notícias."),("Let's {{rope in}} a volunteer.","Vamos recrutar um voluntário."),("This loan will {{tide us over}}.","Este empréstimo nos socorrerá por um tempo."),("Don't {{fob off}} the customer.","Não enrole o cliente.")],"“Rope in” significa…",["recrutar","amarrar","desistir"],0,"Recrutar."),
83006:("Verbos de estado","**Know, love, belong, seem, own** quase não usam *-ing*; alguns mudam de sentido: *is difficult* × *is being difficult*.",[("This book {{belongs}} to my sister.","Este livro pertence à minha irmã."),("I {{know}} the answer.","Sei a resposta."),("He {{is being}} difficult today.","Ele está sendo difícil hoje."),("She {{seems}} tired.","Ela parece cansada.")],"Qual está certa?",["I am knowing him.","I know him.","I am know him."],1,"Know não usa -ing."),
83007:("always + contínuo","**Always / constantly + presente contínuo** expressa irritação com algo repetido.",[("He's {{always leaving}} the lights on.","Ele está sempre deixando as luzes acesas."),("She's {{constantly complaining}}.","Ela está sempre reclamando."),("He always {{leaves}} at six.","Ele sempre sai às seis."),("They're {{forever arguing}}.","Eles vivem discutindo.")],"Qual expressa irritação?",["He always leaves at six.","He's always leaving his socks around.","He leaves."],1,"Always + contínuo."),
83008:("Present perfect × passado","**Present perfect** liga ao presente (sem hora); **past simple** com tempo terminado; **ago** pede passado.",[("I've {{recently moved}} to a new flat.","Mudei recentemente para um novo apartamento."),("We met two years {{ago}}.","Nos conhecemos há dois anos."),("I {{lost}} my keys yesterday.","Perdi minhas chaves ontem."),("I've {{lost}} my keys — can you help?","Perdi as chaves — pode ajudar?")],"Qual combina com “yesterday”?",["I have lost it yesterday.","I lost it yesterday.","I had lost it yesterday."],1,"Tempo terminado: past simple."),
83009:("since / for / ago / by / until","**Since** = ponto de partida; **for** = duração; **by** = prazo; **until** = até quando continua.",[("I've lived here {{since}} 2015.","Moro aqui desde 2015."),("I've lived here {{for}} ten years.","Moro aqui há dez anos."),("Finish the report {{by}} Friday.","Termine o relatório até sexta."),("I'll wait {{until}} the meeting ends.","Esperarei até a reunião acabar.")],"Qual indica prazo final?",["until Friday","by Friday","since Friday"],1,"By."),
940002:("the more …, the more …","**The + comparativo, the + comparativo**: as duas partes se completam.",[("{{The more}} guests arrive, {{the less}} we can talk.","Quanto mais convidados chegam, menos conversamos."),("{{The faster}} you run, {{the sooner}} you arrive.","Quanto mais rápido você corre, mais cedo chega."),("{{The more difficult}} it is, {{the more}} I learn.","Quanto mais difícil, mais eu aprendo."),("{{The sooner}}, the better.","Quanto antes, melhor.")],"Complete: “The more you practice, ___ you improve.”",["the more","most","more"],0,"The more …, the more …"),
83010:("Formas de futuro","**Will** = decisão na hora; **going to** = plano/evidência; **presente contínuo** = arranjo; **presente simples** = horário.",[("I'{{ll pour}} you some tea.","Vou servir um chá para você."),("It's {{going to rain}}.","Vai chover (nuvens no céu)."),("I'm {{meeting}} her at six.","Vou encontrá-la às seis."),("The train {{leaves}} at nine.","O trem parte às nove.")],"Qual é um horário fixo?",["I'll leave.","The train leaves at nine.","I'm going to leave."],1,"Presente simples."),
83011:("be about to / be due to","**Be about to + base** = prestes a; **be due to** = previsto para; **on the point of -ing**.",[("The module {{is about to}} land.","O módulo está prestes a pousar."),("The crew {{is due to}} return on Sunday.","A tripulação deve voltar no domingo."),("I was {{on the point of}} leaving.","Eu estava prestes a sair."),("The bus {{is due}} at six.","O ônibus deve chegar às seis.")],"“About to” significa…",["muito perto de acontecer","há muito tempo","nunca"],0,"Iminente."),
83012:("Futuro no passado","**Was going to / would / was to + base**: o futuro visto do passado.",[("I {{was going to}} call you, but I forgot.","Eu ia ligar para você, mas esqueci."),("She said she {{would}} come.","Ela disse que viria."),("He {{was to}} become a writer.","Ele viria a ser escritor."),("We {{had intended to}} stay longer.","Pretendíamos ficar mais tempo.")],"“I was going to call” indica…",["intenção que não se realizou","algo que fiz","um plano futuro"],0,"Não se realizou."),
83013:("Revisão de tempos","Cada verbo tem uma razão: **past simple** (fato), **past perfect** (antes), **present perfect** (liga ao presente), **futuro** (plano).",[("She reconsidered because she {{had heard}} new facts.","Ela reconsiderou porque tinha ouvido fatos novos."),("I {{'ve decided}} to accept the offer.","Decidi aceitar a oferta."),("They {{will announce}} it tomorrow.","Eles anunciarão amanhã."),("We {{were having}} dinner when it began.","Estávamos jantando quando começou.")],"Qual liga o passado ao presente?",["I have decided.","I decided yesterday.","I had decided before."],0,"Present perfect."),
83014:("will / would: comportamento típico","**Will** = comportamento típico no presente; **would** = no passado. Estados: *used to*.",[("She {{will always take}} the same route.","Ela sempre pega a mesma rota."),("He {{would arrive}} early every day.","Ele chegava cedo todo dia."),("Accidents {{will happen}}.","Acidentes acontecem."),("She {{used to be}} a nurse.","Ela era enfermeira.")],"Qual é um ESTADO (não serve would)?",["He would arrive early.","She used to be a nurse.","We would walk."],1,"Estado: used to."),
940003:("make a case","**Make a case, draw a conclusion, reach an agreement, meet expectations**.",[("Let me {{make a case}} for a new approach.","Deixe-me defender uma nova abordagem."),("We can {{draw a conclusion}} from the data.","Podemos tirar uma conclusão dos dados."),("They finally {{reached an agreement}}.","Eles finalmente chegaram a um acordo."),("The product didn't {{meet expectations}}.","O produto não atendeu às expectativas.")],"Qual está certa?",["do a case","make a case","take a case"],1,"Make a case."),
83015:("Perfect + passivo","**Has/have been + particípio**, **had been + particípio**, **is/are being + particípio**.",[("The area {{has been evacuated}}.","A área foi evacuada."),("It {{is being repaired}}.","Está sendo consertado."),("The files {{had been deleted}} by then.","Os arquivos já tinham sido apagados."),("Bridges {{are being built}} now.","Pontes estão sendo construídas agora.")],"Qual indica um processo em andamento?",["It was repaired.","It is being repaired.","It has repaired."],1,"Is being + particípio."),
83016:("just / already / still / yet","**Just** = acabou de; **already** = antes do esperado; **yet** = até agora (neg./perg.); **still** = continua.",[("He {{still}} hasn't answered.","Ele ainda não respondeu."),("She has {{already}} left.","Ela já saiu."),("Have you finished {{yet}}?","Você já terminou?"),("I've {{just}} heard the news.","Acabei de ouvir a notícia.")],"Onde fica “still” na negativa?",["still hasn't","hasn't still","hasn't yet still"],0,"Before hasn't."),
83017:("Passado × hoje","**Used to** (antes) × **now / nowadays** (hoje); **didn't use to** nega o hábito antigo.",[("People {{used to write}} long letters.","As pessoas escreviam cartas longas."),("{{Nowadays}}, they text each other.","Hoje em dia, mandam mensagens."),("We {{didn't use to}} have phones.","Não tínhamos celulares."),("{{These days}}, everything is online.","Hoje, tudo é on-line.")],"“Didn't use to” = …",["antes não era habitual","agora não é","nunca será"],0,"Hábito antigo negado."),
83018:("Estado resultante","**Be + particípio** descreve o estado: *The window is broken.* Diferente de ação: *was broken by a boy*.",[("The window {{is broken}}.","A janela está quebrada."),("The road {{is blocked}}.","A estrada está bloqueada."),("The window {{was broken}} by a boy.","A janela foi quebrada por um menino."),("The shop {{is closed}} on Sundays.","A loja fica fechada aos domingos.")],"Qual descreve só o estado?",["The window was broken by a boy.","The window is broken.","A boy broke it."],1,"Is broken."),
83019:("Passado com sentido de presente","**It's high time + passado**, **I'd rather + passado**, **suppose + passado**: tempo gramatical passado, sentido atual.",[("It's {{high time}} we {{left}}.","Já é hora de irmos."),("I'd rather you {{didn't tell}} anyone.","Prefiro que você não conte a ninguém."),("{{Suppose}} you {{won}} the lottery?","E se você ganhasse na loteria?"),("It's about time he {{apologized}}.","Já é hora de ele pedir desculpas.")],"“It's time we left” fala de…",["agora","ontem","um passado real"],0,"Presente."),
940004:("the ball is in your court","**The ball is in your court** = a decisão é sua; **play hardball**; **stand your ground**; **move the goalposts**.",[("{{The ball is in your court}} now.","Agora a decisão é sua."),("They decided to {{play hardball}}.","Eles decidiram endurecer."),("{{Stand your ground}}!","Mantenha sua posição!"),("Don't {{move the goalposts}}.","Não mude as regras no meio do jogo.")],"“Move the goalposts” =",["mudar as regras","mexer o gol","jogar bem"],0,"Mudar as regras."),
83020:("Perguntas indiretas","**Ordem de afirmação**, sem do/does: *Could you tell me where the station is?* Com sim/não: **if / whether**.",[("Could you tell me where the station {{is}}?","Poderia me dizer onde fica a estação?"),("Do you know {{whether}} the bank is open?","Você sabe se o banco está aberto?"),("I wonder {{if}} she's coming.","Será que ela vem?"),("Can you tell me what time it {{starts}}?","Pode me dizer a que horas começa?")],"Qual está certa?",["Could you tell me where is the station?","Could you tell me where the station is?","Could you tell me where does the station?"],1,"Ordem de afirmação."),
83021:("Question tags avançadas","A tag segue o auxiliar: *You'd like tea, wouldn't you?* Depois de **Let's**: *shall we?* Depois de **I am**: *aren't I?*",[("You'd like some tea, {{wouldn't you}}?","Você gostaria de chá, não gostaria?"),("Let's go, {{shall we}}?","Vamos, está bem?"),("I'm late, {{aren't I}}?","Estou atrasado, não estou?"),("Open the door, {{will you}}?","Abra a porta, pode ser?")],"Complete: “I am right, ___?”",["amn't I","aren't I","isn't I"],1,"I am → aren't I."),
83022:("do enfático","**Do / does / did + base** dá ênfase: *I do love this book!*",[("I {{do love}} this book!","Eu realmente adoro este livro!"),("He {{did warn}} us about the rain.","Ele de fato nos avisou da chuva."),("She {{does care}} about you.","Ela realmente se importa com você."),("Please {{do come}} in.","Por favor, entre.")],"O que o “do” enfático faz?",["dá ênfase","nega","pergunta"],0,"Ênfase."),
83023:("Perguntas-eco","**Repita a parte importante** com tom subindo para mostrar surpresa: *— I quit. — You quit?*",[("— I quit my job. — You {{quit your job}}?","— Pedi demissão. — Você pediu demissão?"),("— He lives in Oslo. — He lives {{WHERE}}?","— Ele mora em Oslo. — Mora ONDE?"),("{{Really}}? {{Seriously}}?","Sério? Sério mesmo?"),("— I won. — You {{won}}?","— Eu ganhei. — Você ganhou?")],"Para que serve a pergunta-eco?",["mostrar surpresa ou confirmar","dar uma ordem","encerrar"],0,"Confirmar/surpresa."),
940005:("reclamar com firmeza","**I'd like to lodge a complaint. This is unacceptable. I demand a refund.**",[("{{I'd like to lodge a complaint}}.","Gostaria de registrar uma reclamação."),("{{This is unacceptable}}.","Isto é inaceitável."),("{{I demand a refund}}.","Exijo reembolso."),("{{I expect an explanation}}.","Espero uma explicação.")],"“Lodge a complaint” =",["registrar reclamação","hospedar","alugar"],0,"Registrar."),
83024:("Sequência de tempos","Com verbo principal no passado, a subordinada **recua**: *was, had been, would*.",[("She said she {{was}} tired.","Ela disse que estava cansada."),("He said he {{had never lied}}.","Ele disse que nunca tinha mentido."),("He said he {{would come}}.","Ele disse que viria."),("They told us the shop {{had closed}}.","Disseram que a loja tinha fechado.")],"“I will help” → He said he ___ help.",["will","would","had"],1,"Will → would."),
83025:("Condicionais mistas","**If + past perfect, would + base**: condição passada, resultado no presente.",[("If I {{had accepted}}, I {{would be}} abroad now.","Se eu tivesse aceitado, estaria no exterior agora."),("If she {{hadn't left}}, she {{would be}} here.","Se ela não tivesse saído, estaria aqui."),("If we {{had saved}} more, we {{wouldn't be}} broke.","Se tivéssemos poupado mais, não estaríamos sem dinheiro."),("If he {{had studied}}, he {{would be}} a judge.","Se ele tivesse estudado, seria juiz.")],"“Now” no resultado indica…",["condicional mista","zero conditional","first conditional"],0,"Passado → presente."),
83026:("Condicional invertido","**Had I known** = if I had known; **Should you need** = if you should need; **Were I you** = if I were you.",[("{{Had I known}}, I would have called.","Se eu soubesse, teria ligado."),("{{Should you need}} help, call me.","Se precisar de ajuda, ligue-me."),("{{Were I you}}, I'd accept.","Se eu fosse você, aceitaria."),("{{Had it not been for}} her, we'd have failed.","Não fosse por ela, teríamos fracassado.")],"“Had I known” equivale a…",["If I had known","If I know","If I knew"],0,"Inversão."),
83027:("wish / if only","**Wish / if only** pedem um tempo atrás: presente → passado; passado → past perfect; queixa → would.",[("I {{wish I had}} more time.","Queria ter mais tempo."),("{{If only I had listened}} to you.","Se ao menos eu tivesse ouvido você."),("I {{wish he would stop}}.","Queria que ele parasse."),("I {{wish I were}} taller.","Queria ser mais alto.")],"“I wish he would stop” expressa…",["queixa sobre algo repetido","gratidão","um plano"],0,"Queixa."),
83028:("as if / as though","Para o irreal: **passado**; para passado irreal: **past perfect**.",[("He talks {{as if he owned}} the place.","Ele fala como se fosse dono do lugar."),("She looked {{as though she had seen}} a ghost.","Ela parecia ter visto um fantasma."),("It looks {{as if}} it will rain.","Parece que vai chover."),("He acts {{as if}} nothing happened.","Ele age como se nada tivesse acontecido.")],"Qual está certa?",["as if he is the boss","as if he were the boss","as if he will be boss"],1,"Irreal: were."),
940006:("scrape by / make do","**Scrape by** = mal sobreviver; **eke out** = tirar o mínimo; **make do** = contentar-se; **muddle through**.",[("We {{scrape by}} from odd jobs.","Mal sobrevivemos de bicos."),("We {{make do}} with old furniture.","Nos arranjamos com móveis velhos."),("We somehow {{muddle through}}.","De algum jeito nos viramos."),("She {{eked out}} a living.","Ela ganhou o mínimo para viver.")],"“Make do with” =",["contentar-se com","fazer com","produzir"],0,"Contentar-se."),
83029:("It's time / high time","**It's time + sujeito + passado**; mesmo sujeito: **time to + infinitivo**; **about time** = impaciência.",[("It's time we {{made}} a decision.","Já é hora de decidirmos."),("It's time {{to decide}}.","É hora de decidir."),("{{About time}} you called!","Já era hora de você ligar!"),("It's high time he {{grew up}}.","Já é hora de ele amadurecer.")],"Qual está certa?",["It's time we make.","It's time we made.","It's time we will make."],1,"Passado."),
83030:("would rather / had better","**I'd rather + base** (preferência); **had better + base** (conselho forte); outra pessoa: **I'd rather you + passado**.",[("I'd {{rather stay}} in.","Prefiro ficar em casa."),("You'd {{better hurry}}.","É melhor você se apressar."),("I'd rather you {{stayed}}.","Prefiro que você ficasse."),("You'd better {{not}} be late.","É melhor não se atrasar.")],"Qual está certa?",["I'd rather to stay.","I'd rather stay.","I'd rather staying."],1,"Rather + base."),
83031:("Condição sem if","**Unless** = if not; **provided that / as long as** = só se. Depois: presente.",[("{{Unless}} you pay, we won't play.","A menos que você pague, não jogamos."),("You may go {{provided that}} you call.","Você pode ir contanto que ligue."),("{{As long as}} it's safe, I'll agree.","Desde que seja seguro, eu concordo."),("Hurry, {{otherwise}} we'll miss it.","Apresse-se, senão perderemos.")],"Qual está certa?",["Unless it will rain, we go.","Unless it rains, we'll go.","Unless it rained, we go."],1,"Presente após unless."),
83032:("Subjuntivo formal","Depois de **suggest, insist, demand, recommend** e de adjetivos como **essential**: *that + sujeito + base*.",[("I suggest that he {{see}} a doctor.","Sugiro que ele consulte um médico."),("It is essential that everyone {{be}} present.","É essencial que todos estejam presentes."),("They demand that she {{resign}}.","Eles exigem que ela renuncie."),("I recommend that he {{not go}}.","Recomendo que ele não vá.")],"Qual está certa?",["I suggest that he sees.","I suggest that he see.","I suggest that he seeing."],1,"Base sem -s."),
83033:("Passado hipotético","**Could have** = possibilidade não realizada; **might have** = suposição; **needn't have** = fez sem precisar.",[("I {{could have gone}}.","Eu poderia ter ido."),("She {{might have missed}} it.","Ela pode ter perdido isso."),("You {{needn't have bought}} flowers.","Você não precisava ter comprado flores."),("We {{would have won}} with practice.","Teríamos ganhado com treino.")],"“Needn't have” =",["fez sem necessidade","não fez","devia ter feito"],0,"Desnecessário."),
940007:("-ever","**Whatever, whoever, wherever, whenever, whichever** = qualquer …",[("{{Whatever}} you decide, I'll support you.","Qualquer coisa que decida, apoiarei você."),("{{Whoever}} calls, take a message.","Quem quer que ligue, anote o recado."),("{{Wherever}} you go, call me.","Aonde quer que vá, ligue para mim."),("Take {{whichever}} you like.","Pegue o que preferir.")],"“Whenever” =",["a qualquer momento","em lugar nenhum","às vezes"],0,"Qualquer hora."),
83034:("Condicionais em negociações","**First** (oferta real), **second** (proposta mais polida), **otherwise** (consequência).",[("If you {{lower}} the price, we'll sign.","Se você baixar o preço, assinaremos."),("If you {{lowered}} the price, we {{would sign}}.","Se você baixasse o preço, assinaríamos."),("{{Otherwise}}, we'll look elsewhere.","Caso contrário, procuraremos em outro lugar."),("{{Provided}} you deliver on time, we'll renew.","Desde que entregue no prazo, renovaremos.")],"Qual é mais polida?",["If you lower…, we'll sign.","If you lowered…, we would sign.","You lower, we sign."],1,"Second conditional."),
83035:("Passado real × irreal","Real: **If he was angry, he didn't show it** (fato). Irreal: **If he were angry, he would say so** (hipótese).",[("If he {{was}} angry, he didn't show it.","Se estava com raiva, não demonstrou."),("If he {{were}} angry, he {{would say}} so.","Se estivesse com raiva, diria."),("If it {{was}} true, nobody noticed.","Se era verdade, ninguém notou."),("If I {{were}} you, I'd stay.","Se eu fosse você, ficaria.")],"Qual é hipótese sobre o presente?",["If he was late, nobody cared.","If he were late, we would wait.","If he is late, we wait."],1,"Were."),
83036:("even if / only if","**Even if** = a condição não muda o resultado; **only if** = única condição.",[("{{Even if}} it rains, we'll go.","Mesmo que chova, iremos."),("You can enter {{only if}} you have a ticket.","Você só entra se tiver bilhete."),("Call me {{if necessary}}.","Ligue-me se necessário."),("{{If not}}, we'll leave.","Se não, partiremos.")],"“Only if” indica…",["única condição","condição irrelevante","possibilidade remota"],0,"Única condição."),
83037:("wish + would","**Wish + would** reclama do que alguém faz. Não use com o próprio sujeito.",[("I {{wish he would listen}} more.","Queria que ele ouvisse mais."),("I wish it {{would stop}} raining.","Queria que parasse de chover."),("I wish I {{were}} taller.","Queria ser mais alto."),("I wish they {{wouldn't shout}}.","Queria que não gritassem.")],"Qual está certa?",["I wish I would be taller.","I wish I were taller.","I wish I will be taller."],1,"Wish + were."),
940008:("take precautions","**Take precautions** = prevenir; **run a risk**; **shed light on** = esclarecer; **set a precedent**.",[("We must {{take precautions}} before entering.","Devemos tomar precauções antes de entrar."),("You {{run a risk}} by waiting.","Você corre um risco ao esperar."),("This study {{sheds light on}} the problem.","Este estudo esclarece o problema."),("It could {{set a precedent}}.","Pode criar um precedente.")],"“Shed light on” =",["esclarecer","derramar luz","acender"],0,"Esclarecer."),
83038:("Revisão: condicionais B2","**Zero, first, second, third, mixed**; *had it not been for* = não fosse por.",[("If you heat ice, it {{melts}}.","Se aquece gelo, ele derrete."),("If I {{were}} you, I'd apologize.","Se eu fosse você, pediria desculpas."),("If I {{had known}}, I {{would have come}}.","Se eu soubesse, teria vindo."),("{{Had it not been for}} you, I'd have failed.","Não fosse por você, eu teria fracassado.")],"Qual é o third conditional?",["If I had known, I'd have come.","If I knew, I'd come.","If I know, I'll come."],0,"If + had + particípio."),
83039:("Inversão com negativos","Advérbio negativo no começo: **auxiliar antes do sujeito**. *Never have I seen…*",[("{{Never have I seen}} such a face.","Nunca vi um rosto assim."),("{{Seldom does he smile}}.","Raramente ele sorri."),("{{Not only is he rich}}, but also kind.","Ele não é só rico, é também gentil."),("{{Hardly had we arrived}} when it rained.","Mal tínhamos chegado quando choveu.")],"Qual está certa?",["Never I have seen it.","Never have I seen it.","Never I saw it."],1,"Inversão."),
83040:("only + inversão","**Only then / only after / only when** no começo: inverta.",[("{{Only then did he understand}}.","Só então ele entendeu."),("{{Only after the storm did we leave}}.","Só depois da tempestade saímos."),("{{Only when you ask will I help}}.","Só quando você pedir eu ajudarei."),("{{Only by working hard}} can you succeed.","Só trabalhando duro você tem sucesso.")],"Qual está certa?",["Only then he understood.","Only then did he understand.","Only then he did understand."],1,"Did + sujeito."),
83041:("so / such + inversão","**So + adjetivo** ou **such + be** no começo dá efeito literário.",[("{{So angry was he}} that he shouted.","Tão furioso estava ele que gritou."),("{{Such was his fear}} that he froze.","Tamanho era o medo dele que ele congelou."),("{{So loud was the noise}} that we covered our ears.","Tão alto era o barulho que tapamos os ouvidos."),("He was so angry that he shouted.","Ele estava tão furioso que gritou.")],"A inversão com “so” soa…",["literária e dramática","informal","errada"],0,"Estilo literário."),
83042:("Inversão de lugar","Expressão de lugar no começo: o verbo vem **antes** do sujeito (com substantivo).",[("{{On the hill stood}} an old house.","No morro havia uma casa antiga."),("{{Beyond the fields lay}} a village.","Além dos campos ficava um vilarejo."),("{{Down the stream floated}} a boat.","Rio abaixo flutuava um barco."),("{{Here comes}} the bus.","Aí vem o ônibus.")],"Com pronome, a inversão…",["não acontece","é obrigatória","é opcional"],0,"Com pronome não inverte: Here he comes."),
940009:("gírias de redes","**Lowkey**, **highkey**, **flex**, **stan**, **doomscroll**, **clapback**.",[("{{Lowkey}}, I'm tired of this place.","Na real, estou cansado deste lugar."),("She's such a {{stan}} of that band.","Ela é fã devota daquela banda."),("Stop {{doomscrolling}} before bed.","Pare de rolar notícias ruins antes de dormir."),("That was a {{clapback}}!","Foi uma resposta afiada!")],"“Flex” =",["se exibir","dobrar","esticar"],0,"Exibir-se."),
83043:("it-cleft","**It is/was + parte destacada + that/who** destaca um elemento.",[("It was {{me who}} broke the vase.","Fui eu quem quebrou o vaso."),("It was {{the invitation that}} surprised her.","Foi o convite que a surpreendeu."),("It was {{yesterday that}} we met.","Foi ontem que nos conhecemos."),("It is {{her attitude that}} bothers me.","É a atitude dela que me incomoda.")],"Para pessoa, use…",["who","which","where"],0,"Who."),
83044:("wh-cleft","**What + sujeito + verbo + is/was** dá destaque.",[("{{What I need is}} a holiday.","O que preciso é de férias."),("{{What really matters is}} being free.","O que realmente importa é ser livre."),("{{What I want is}} to rest.","O que quero é descansar."),("{{What happened was}} a mistake.","O que aconteceu foi um erro.")],"Qual está certa?",["What I need a holiday is.","What I need is a holiday.","What is I need holiday."],1,"What + S + V + is."),
83045:("Antecipação (fronting)","Mova uma parte para o começo: **Strange though it seems**; **Try as I might**.",[("{{Strange though it seems}}, it's true.","Por mais estranho que pareça, é verdade."),("{{Try as I might}}, I can't open it.","Por mais que eu tente, não consigo abrir."),("{{Young though he was}}, he led them.","Embora jovem, ele os liderou."),("{{Much as I like him}}, I disagree.","Por mais que eu goste dele, discordo.")],"“Try as I might” equivale a…",["Although I try hard","Because I try","If I try"],0,"Por mais que tente."),
83046:("Reflexivos enfáticos","O reflexivo dá **ênfase**: *I myself saw it. The mayor himself signed it.*",[("I {{myself}} saw the report.","Eu mesmo vi o relatório."),("The mayor {{himself}} signed it.","O próprio prefeito assinou."),("I saw it {{myself}}.","Eu vi com meus próprios olhos."),("She did it {{herself}}.","Ela mesma fez.")],"“By myself” significa…",["sozinho","comigo","para mim"],0,"Sozinho."),
83047:("Intensificadores","Adjetivos extremos: **absolutely / utterly**; graduáveis: **very / rather / fairly**.",[("The view was {{absolutely}} wonderful.","A vista foi absolutamente maravilhosa."),("It's {{very}} cold.","Está muito frio."),("I'm {{utterly}} exhausted.","Estou totalmente exausto."),("It's {{fairly}} good.","É razoavelmente bom.")],"Qual está certa?",["very wonderful","absolutely wonderful","absolutely cold"],1,"Extremo + absolutely."),
940010:("regardless / nonetheless","**Regardless of / nonetheless** contrastam; **albeit** = embora; **thereby** = resultado; **inasmuch as**.",[("{{Regardless of}} the cost, he tried.","Independentemente do custo, ele tentou."),("A good plan, {{albeit}} a risky one.","Um bom plano, embora arriscado."),("It was late; {{nonetheless}}, we went.","Era tarde; mesmo assim, fomos."),("He signed, {{thereby}} agreeing.","Ele assinou, concordando assim.")],"“Albeit” =",["embora","portanto","além disso"],0,"Embora."),
83048:("Elipse e substituição","**I think so / I hope not**; **so can she**, **neither do I**.",[("— Is it open? — {{I think so}}.","— Está aberto? — Acho que sim."),("— Rain? — {{I hope not}}.","— Chuva? — Espero que não."),("He can swim, and {{so can she}}.","Ele sabe nadar, e ela também."),("I don't like fish. {{Neither do I}}.","Não gosto de peixe. Nem eu.")],"“Neither do I” concorda com…",["frase negativa","frase positiva","pergunta"],0,"Negativa."),
83049:("Paralelismo","**Repita a estrutura** para ritmo e ênfase.",[("We shall fight {{on the beaches}},","Lutaremos nas praias,"),("we shall fight {{in the streets}},","lutaremos nas ruas,"),("we shall fight {{in the hills}}.","lutaremos nas colinas."),("Use it in speeches and ads.","Use em discursos e anúncios.")],"Qual muda na repetição?",["o lugar","o verbo","o sujeito"],0,"O lugar."),
83050:("Perguntas retóricas","Não pedem resposta: **Isn't it obvious?** **Who can blame him?** **What's the point?**",[("{{Isn't it obvious}}?","Não é óbvio?"),("{{Who can blame him}}?","Quem pode culpá-lo?"),("{{What's the point}}?","Qual é o sentido?"),("{{Why would anyone}} do that?","Por que alguém faria isso?")],"“Who can blame him?” quer dizer…",["ninguém pode culpá-lo","quem é culpado?","eu culpo"],0,"Afirmação."),
83051:("Subestimação","**Understatement** diz menos do que a situação merece: *a bit damp* numa enchente.",[("It's {{a bit damp}} — the house is flooded!","Está um pouco úmido — a casa está alagada!"),("{{Not bad}}, for a masterpiece.","Nada mau, para uma obra-prima."),("{{Quite interesting}}, the explosion.","Bastante interessante, a explosão."),("A {{little}} chilly at the Pole.","Um pouco frio no Polo.")],"O humor está na…",["distância entre palavras e fato","repetição","rima"],0,"Contraste."),
940011:("iron out / hammer out","**Iron out** = resolver detalhes; **hammer out** = chegar a acordo; **hash out / thrash out** = discutir a fundo.",[("We need to {{iron out}} the problems.","Precisamos resolver os problemas."),("We {{hammered out}} a deal.","Fechamos um acordo."),("Let's {{hash out}} the details.","Vamos discutir os detalhes a fundo."),("They {{thrashed out}} a plan.","Eles debateram até chegar a um plano.")],"“Hammer out a deal” =",["chegar a um acordo","bater","quebrar"],0,"Acordo."),
83052:("Referência","**The former / the latter**, **respectively**, **whereas** ligam ideias sem repetir.",[("I have a cat and a dog; {{the former}} is white.","Tenho um gato e um cachorro; o primeiro é branco."),("{{The latter}} is brown.","O segundo é marrom."),("Ann and Bo are 20 and 30, {{respectively}}.","Ann e Bo têm 20 e 30 anos, respectivamente."),("She likes tea, {{whereas}} he likes coffee.","Ela gosta de chá, enquanto ele gosta de café.")],"“The latter” =",["o segundo mencionado","o primeiro mencionado","o último de todos"],0,"O segundo."),
83053:("Conectores","**Moreover** (acrescenta), **nevertheless** (contrasta), **consequently** (resultado).",[("{{Moreover}}, it saves time.","Além disso, economiza tempo."),("It rained. {{Nevertheless}}, we went.","Choveu. Mesmo assim, fomos."),("{{Consequently}}, prices fell.","Consequentemente, os preços caíram."),("He studied; {{therefore}}, he passed.","Ele estudou; portanto, passou.")],"Qual mostra resultado?",["moreover","consequently","nevertheless"],1,"Consequently."),
83054:("Hedging","**Seems, appears, tend to, probably, to some extent, may** suavizam uma afirmação.",[("The data {{appears to}} support the idea.","Os dados parecem apoiar a ideia."),("It {{seems}} likely.","Parece provável."),("People {{tend to}} agree.","As pessoas tendem a concordar."),("{{To some extent}}, it works.","Até certo ponto, funciona.")],"Qual é mais cuidadoso?",["The data proves it.","The data appears to support it.","The data is it."],1,"Hedging."),
83055:("Concessão","**Admittedly… However… Granted… That said…** reconhecem um ponto antes de contrariar.",[("{{Admittedly}}, it's expensive. {{However}}, it's worth it.","É verdade que é caro. Porém vale a pena."),("{{Granted}}, he made a mistake, but…","Admito que ele errou, mas…"),("It's slow. {{That said}}, it's reliable.","É lento. Dito isso, é confiável."),("{{Despite}} the rain, we walked.","Apesar da chuva, caminhamos.")],"“Granted” =",["admito","concedido","dado"],0,"Admito."),
83056:("Passivo com verbos de relato","**It is said that…** / **She is said to have been…**: não nomeia a fonte.",[("{{It is said that}} she was bored.","Diz-se que ela estava entediada."),("She {{is said to have been}} bored.","Diz-se que ela estava entediada."),("He {{is believed to be}} rich.","Acredita-se que ele seja rico."),("Prices {{are expected to}} rise.","Espera-se que os preços subam.")],"“Is believed to be” =",["acredita-se que seja","acredita ser","acreditou"],0,"Passivo impessoal."),
940012:("remember to / -ing","**Remember to** (futuro) × **remember -ing** (passado); **stop to** × **stop -ing**; **regret to** × **regret -ing**.",[("{{Remember to lock}} the door.","Lembre-se de trancar a porta."),("I {{remember locking}} it.","Lembro de tê-la trancado."),("He {{stopped to rest}}.","Ele parou para descansar."),("I {{regret telling}} her.","Lamento ter contado a ela.")],"“I regret telling her” =",["lamento ter contado","lamento contar agora","lamentarei"],0,"-ing = passado."),
83057:("Passivo com infinitivo e -ing","Depois de **want, expect, hate, enjoy**: **to be + particípio** / **being + particípio**.",[("She expects {{to be treated}} fairly.","Ela espera ser tratada com justiça."),("He hates {{being told}} what to do.","Ele odeia que lhe digam o que fazer."),("I enjoy {{being asked}} for advice.","Gosto de que me peçam conselhos."),("They want {{to be paid}} on time.","Querem ser pagos em dia.")],"Qual está certa?",["He hates telling.","He hates being told.","He hates to told."],1,"Being told."),
83058:("Dois objetos, duas passivas","**Give, offer, send, show**: a pessoa pode ser sujeito (*Oliver was given a bowl*) ou a coisa (*A bowl was given to Oliver*).",[("Oliver {{was given}} a bowl of soup.","Oliver recebeu uma tigela de sopa."),("A bowl of soup {{was given to}} Oliver.","Uma tigela de sopa foi dada a Oliver."),("She {{was offered}} a job.","Ofereceram-lhe um emprego."),("We {{were shown}} the way.","Mostraram-nos o caminho.")],"Qual é a mais comum?",["A person as subject","A thing as subject","Ambas iguais"],0,"A pessoa."),
}
